import React, { useState, useEffect } from "react";
import { View, FlatList, Text } from "react-native";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { Nota } from "./src/componentes/";
import NotaEditor from "./src/componentes/NotaEditor";

export default function App() {
  const [notas, setNotas] = useState([]);

  const mostraNotas = async () => {
    try {
      const todasChaves = await AsyncStorage.getAllKeys();
      console.log("Chaves encontradas:", todasChaves);

      const todasNotas = await AsyncStorage.multiGet(todasChaves);
      console.log("Notas carregadas:", todasNotas);

      // Filtra notas vazias e undefined
      const notasFiltradas = todasNotas.filter(([chave, valor]) => 
        valor !== null && valor !== undefined && valor.trim() !== ""
      );

      console.log("Notas filtradas:", notasFiltradas);
      setNotas(notasFiltradas);
    } catch (error) {
      console.error("Erro ao carregar notas:", error);
    }
  };

  useEffect(() => {
    mostraNotas();
  }, []);

  return (
    <View style={{ flex: 1, paddingTop: 50 }}>
      <Text style={{ fontSize: 24, fontWeight: "bold", textAlign: "center", marginBottom: 20 }}>
        Minhas Notas
      </Text>

      <FlatList
        data={notas}
        keyExtractor={(item) => item[0]} // Usa a chave como id
        renderItem={({ item }) => {
          console.log("Renderizando item:", item);
          return <Nota item={item} />
        }}
        ListEmptyComponent={
          <Text style={{ textAlign: "center", marginTop: 20, padding: 16, color: "#666" }}>
            Nenhuma nota encontrada. Clique no + para criar uma nova nota.
          </Text>
        }
      />
      <NotaEditor mostraNotas={mostraNotas} />
    </View>
  );
}
